def dbhash():
    result={}
    for table,order in [('m_employee','employee_id'),('t_career','career_id'),('m_code','category_id,code'),('m_code_category','category_id')]:
        value=rt.sql('SELECT * FROM dbo.'+table+' ORDER BY '+order+' FOR JSON PATH,INCLUDE_NULL_VALUES;');result[table]=__import__('hashlib').sha256(value.encode()).hexdigest()
    return result
