async def natural_order(p):
    # Store only actual node references, never expected order or expected values.
    await p.evaluate('''()=>{const n=[...document.querySelectorAll('a[href],button,input,select,textarea,summary,[tabindex]')].filter(e=>e.tabIndex>=0&&!e.disabled&&e.type!=='hidden'&&e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden');window.__actualFocusable=n.filter((e,i)=>e.type!=='radio'||!e.name||e.checked||!n.some(x=>x.type==='radio'&&x.name===e.name&&x.checked)&&n.findIndex(x=>x.type==='radio'&&x.name===e.name)===i);window.__actualFocusable[0].focus();}''')
    count=await p.evaluate('window.__actualFocusable.length');indices=[];focus=[]
    for i in range(count):
        current=await p.evaluate('''()=>{const n=document.activeElement,s=getComputedStyle(n);return{index:window.__actualFocusable.indexOf(n),id:n.id,itemId:n.dataset.itemId,outline:s.outlineStyle,width:s.outlineWidth};}''');indices.append(current['index']);focus.append(current);await p.keyboard.press('Tab')
    assert indices==list(range(count)),indices
    assert all(x['outline']!='none' and float(x['width'].removesuffix('px'))>=1 for x in focus[1:]),focus
    return {'nodes':focus,'indices':indices,'domCount':count,'natural':indices==list(range(count))}

